  1	import { describe, it, expect } from 'vitest';
  2	import {
  3	  InsightScope,
  4	  InsightSchema,
  5	  KnowledgeStoreSchema,
  6	  PROJECT_SLUG_REGEX,
  7	  type Insight,
  8	  type KnowledgeStore,
  9	} from '../../src/schema/knowledge.js';
 10	
 11	// ─── Fixtures ──────────────────────────────────────────────────────────────
 12	
 13	const validInsight: Insight = {
 14	  id: 1,
 15	  scope: 'global',
 16	  title: 'Use path.join for cross-platform paths',
 17	  content: 'Always use path.join() instead of string concatenation to ensure cross-platform compatibility.',
 18	  category: 'best-practice',
 19	  tags: ['node', 'filesystem', 'cross-platform'],
 20	  source: 'WP-042',
 21	  created_at: '2026-05-28T12:00:00Z',
 22	  confidence: 0.9,
 23	};
 24	
 25	const validRepositoryInsight: Insight = {
 26	  ...validInsight,
 27	  id: 2,
 28	  scope: 'repository',
 29	  repository_name: 'hcp-editor',
 30	};
 31	
 32	const validKnowledgeStore: KnowledgeStore = {
 33	  version: '1.0.0',
 34	  last_updated: '2026-05-28T12:00:00Z',
 35	  next_id: 1,
 36	  insights: [],
 37	};
 38	
 39	// ─── InsightScope ──────────────────────────────────────────────────────────
 40	
 41	describe('InsightScope', () => {
 42	  it("parses 'global' successfully", () => {
 43	    expect(InsightScope.safeParse('global').success).toBe(true);
 44	  });
 45	
 46	  it("parses 'repository' successfully", () => {
 47	    expect(InsightScope.safeParse('repository').success).toBe(true);
 48	  });
 49	
 50	  it("rejects 'project' (removed scope value)", () => {
 51	    expect(InsightScope.safeParse('project').success).toBe(false);
 52	  });
 53	
 54	  it('rejects arbitrary strings', () => {
 55	    expect(InsightScope.safeParse('team').success).toBe(false);
 56	    expect(InsightScope.safeParse('').success).toBe(false);
 57	  });
 58	});
 59	
 60	// ─── PROJECT_SLUG_REGEX ────────────────────────────────────────────────────
 61	
 62	describe('PROJECT_SLUG_REGEX', () => {
 63	  it('accepts valid slugs', () => {
 64	    expect(PROJECT_SLUG_REGEX.test('hcp-editor')).toBe(true);
 65	    expect(PROJECT_SLUG_REGEX.test('some-plan-slug')).toBe(true);
 66	    expect(PROJECT_SLUG_REGEX.test('my_project')).toBe(true);
 67	    expect(PROJECT_SLUG_REGEX.test('abc123')).toBe(true);
 68	    expect(PROJECT_SLUG_REGEX.test('A')).toBe(true);
 69	  });
 70	
 71	  it('rejects slugs with disallowed characters', () => {
 72	    expect(PROJECT_SLUG_REGEX.test('my/project')).toBe(false);
 73	    expect(PROJECT_SLUG_REGEX.test('my\\project')).toBe(false);
 74	    expect(PROJECT_SLUG_REGEX.test('../escape')).toBe(false);
 75	    expect(PROJECT_SLUG_REGEX.test('has space')).toBe(false);
 76	    expect(PROJECT_SLUG_REGEX.test('dot.name')).toBe(false);
 77	  });
 78	
 79	  it('rejects slugs that do not start with alphanumeric', () => {
 80	    expect(PROJECT_SLUG_REGEX.test('-starts-with-dash')).toBe(false);
 81	    expect(PROJECT_SLUG_REGEX.test('_starts-with-underscore')).toBe(false);
 82	  });
 83	});
 84	
 85	// ─── InsightSchema ─────────────────────────────────────────────────────────
 86	
 87	describe('InsightSchema', () => {
 88	  it('accepts a valid global insight', () => {
 89	    expect(InsightSchema.safeParse(validInsight).success).toBe(true);
 90	  });
 91	
 92	  it('accepts a valid repository-scoped insight with repository_name', () => {
 93	    expect(InsightSchema.safeParse(validRepositoryInsight).success).toBe(true);
 94	  });
 95	
 96	  it('accepts a repository-scoped insight without repository_name (storage layer enforces that constraint)', () => {
 97	    // The scope === 'repository' → repository_name required constraint is owned by the
 98	    // storage layer (KnowledgeStoreManager), not by this schema.
 99	    const { repository_name: _removed, ...input } = validRepositoryInsight;
100	    expect(InsightSchema.safeParse(input).success).toBe(true);

101	  });
102	
103	  it('accepts objects with scope: repository, repository_name, and origin_plan', () => {
104	    const input = {
105	      ...validInsight,
106	      scope: 'repository',
107	      repository_name: 'hcp-editor',
108	      origin_plan: 'some-plan-slug',
109	    };
110	    expect(InsightSchema.safeParse(input).success).toBe(true);
111	  });
112	
113	  it('accepts objects omitting both repository_name and origin_plan (both are optional)', () => {
114	    expect(InsightSchema.safeParse(validInsight).success).toBe(true);
115	  });
116	
117	  it('does not populate project_slug on parsed result (field removed from schema)', () => {
118	    const input = { ...validInsight, project_slug: 'some-project' };
119	    const result = InsightSchema.safeParse(input);
120	    expect(result.success).toBe(true);
121	    // Zod strips unknown keys by default; project_slug should not appear
122	    expect((result.data as Record<string, unknown>).project_slug).toBeUndefined();
123	  });
124	
125	  it.each([
126	    'id',
127	    'scope',
128	    'title',
129	    'content',
130	    'category',
131	    'tags',
132	    'source',
133	    'created_at',
134	    'confidence',
135	  ])('rejects when required field "%s" is missing', (field) => {
136	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
137	    const { [field as keyof typeof validInsight]: _removed, ...rest } = validInsight as any;
138	    expect(InsightSchema.safeParse(rest).success).toBe(false);
139	  });
140	
141	  it('accepts when all optional fields are omitted (updated_at, repository_name, origin_plan, superseded_by)', () => {
142	    expect(InsightSchema.safeParse(validInsight).success).toBe(true);
143	  });
144	
145	  it('accepts when all optional fields are present', () => {
146	    const full = {
147	      ...validInsight,
148	      repository_name: 'my-repo',
149	      origin_plan: 'my-plan',
150	      updated_at: '2026-05-28T13:00:00Z',
151	      superseded_by: 5,
152	    };
153	    expect(InsightSchema.safeParse(full).success).toBe(true);
154	  });
155	
156	  it('rejects a non-integer id', () => {
157	    expect(InsightSchema.safeParse({ ...validInsight, id: 1.5 }).success).toBe(false);
158	  });
159	
160	  it('rejects an invalid scope value', () => {
161	    expect(InsightSchema.safeParse({ ...validInsight, scope: 'team' }).success).toBe(false);
162	  });
163	
164	  it('rejects tags that is not an array', () => {
165	    expect(InsightSchema.safeParse({ ...validInsight, tags: 'node' }).success).toBe(false);
166	  });
167	
168	  it('rejects confidence that is not a number', () => {
169	    expect(InsightSchema.safeParse({ ...validInsight, confidence: 'high' }).success).toBe(false);
170	  });
171	
172	  it('rejects confidence values outside 0–1', () => {
173	    expect(InsightSchema.safeParse({ ...validInsight, confidence: 1.5 }).success).toBe(false);
174	    expect(InsightSchema.safeParse({ ...validInsight, confidence: -0.1 }).success).toBe(false);
175	  });
176	
177	  it('accepts confidence boundary values 0 and 1', () => {
178	    expect(InsightSchema.safeParse({ ...validInsight, confidence: 0 }).success).toBe(true);
179	    expect(InsightSchema.safeParse({ ...validInsight, confidence: 1 }).success).toBe(true);
180	  });
181	
182	  it('rejects a non-integer superseded_by value', () => {
183	    expect(InsightSchema.safeParse({ ...validInsight, superseded_by: 2.7 }).success).toBe(false);
184	  });
185	
186	  it('TypeScript type Insight is inferred from schema (no handwritten duplicate interface)', () => {
187	    // Compile-time check: if Insight diverges from InsightSchema this line fails.
188	    const insight: Insight = validInsight;
189	    expect(insight.id).toBe(1);
190	  });
191	});
192	
193	// ─── KnowledgeStoreSchema ──────────────────────────────────────────────────
194	
195	describe('KnowledgeStoreSchema', () => {
196	  it('accepts a valid store with an empty insights array', () => {
197	    expect(KnowledgeStoreSchema.safeParse(validKnowledgeStore).success).toBe(true);
198	  });
199	
200	  it('accepts a valid store with a non-zero next_id', () => {
201	    expect(KnowledgeStoreSchema.safeParse({ ...validKnowledgeStore, next_id: 42 }).success).toBe(true);
202	  });
203	
204	  it('accepts a store with a populated insights array', () => {
205	    const store = { ...validKnowledgeStore, next_id: 2, insights: [validInsight] };
206	    expect(KnowledgeStoreSchema.safeParse(store).success).toBe(true);
207	  });
208	
209	  it('accepts next_id of 0 (initial empty-store value)', () => {
210	    expect(KnowledgeStoreSchema.safeParse({ ...validKnowledgeStore, next_id: 0 }).success).toBe(true);
211	  });
212	
213	  it('rejects a negative next_id', () => {
214	    expect(KnowledgeStoreSchema.safeParse({ ...validKnowledgeStore, next_id: -1 }).success).toBe(false);
215	  });
216	
217	  it('rejects a non-integer next_id', () => {
218	    expect(KnowledgeStoreSchema.safeParse({ ...validKnowledgeStore, next_id: 1.5 }).success).toBe(false);
219	  });
220	
221	  it.each(['version', 'last_updated', 'next_id', 'insights'])(
222	    'rejects when required field "%s" is missing',
223	    (field) => {
224	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
225	      const { [field as keyof typeof validKnowledgeStore]: _removed, ...rest } = validKnowledgeStore as any;
226	      expect(KnowledgeStoreSchema.safeParse(rest).success).toBe(false);
227	    }
228	  );
229	
230	  it('rejects when insights contains an invalid insight object', () => {
231	    const badInsight = { ...validInsight, scope: 'invalid-scope' };
232	    expect(KnowledgeStoreSchema.safeParse({ ...validKnowledgeStore, insights: [badInsight] }).success).toBe(false);
233	  });
234	
235	  it('TypeScript type KnowledgeStore is inferred from schema (no handwritten duplicate interface)', () => {
236	    // Compile-time check: if KnowledgeStore diverges from KnowledgeStoreSchema this line fails.
237	    const store: KnowledgeStore = validKnowledgeStore;
238	    expect(store.next_id).toBe(1);
239	  });
240	});

